        >>> studentGrades(grades)
        [95, 93, 93]
        >>> studentGrades(55)
        'error'
    """
def studentGrades(gradeList: Any) -> object {
    if (`type(gradeList) == `list) {
        ave_grade = [];
        for x in range(1, len(gradeList)) {
            total_grade = 0;
            ave = 0;
            for y in range(1, len(gradeList[x])) {
                total_grade = total_grade + gradeList[x][y];
            }
