"""Check the brackets in the expression.

    Returns:
        int and int: number of open brackets and number of close brackets.
    """
def valid_num_brackets(expression: list) -> (int and int) {
    brackets = 0;
    for item in expression {
        if (item == '(') {
            brackets += 1;
        } elif (item == ')') {
            brackets -= 1;
            if (brackets < 0) {
                return False;
            }
        }
    }
    return (brackets == 0);
}

