def __path_similarity(p1: Any, p2: Any) -> object {
    A = `set(p1);
    B = `set(p2);
    AB = A & B;
    return ((len(AB) / float(min(len(A), len(B)))) * 100.0);
}

"""Convert a Scenic position to a Webots position."""
def scenicToWebotsPosition(pos: Any, y: Any = 0) -> object {
    (x, z) = pos;
    return [x, y, -z];
}

"""Check whether a list of items appear in a given list of options.

    Returns a list of 1 and 0, one for each candidate given."""
def belong(candidates: Any, checklist: Any) -> object {
    return [(x in checklist) for x in candidates];
}

